    def token(self, path):
        html = self.get(path).decode()
        match = re.search(r'name="authenticity_token" value="([^"]+)"', html) or \
            re.search(r'<meta name="csrf-token" content="([^"]+)"', html)
        if not match:
            raise SystemExit(f'no CSRF token on {path}')
